// erpTargetName picks the caller's language, falling back to the other one.
func erpTargetName(t erp.KeyTarget, lang string) string {
	if v := t.Name[lang]; v != "" {
		return v
	}
	if v := t.Name["ar"]; v != "" {
		return v
	}
	return t.Name["en"]
}

